"""A pursuit start leaves the field to the other owners for a while.

Live g1288 2026-11-20 12:00-13:30 (v1249): 77 pursuits were queued and 65
redirects were committed in 1 h 40 m, none of them entered the boss. Because
``boss_pursuit.step`` owns the first map frame after every close, the map flow
never got to start a wave from a castle and the visible-camp recall never got
the frame or the month it needed: month 64-3 closed with zero launches and
zero departures. ``PURSUIT_START_GAP`` makes the pursuit yield for a bounded
number of ticks after each start.
"""
from types import SimpleNamespace

from docich.hanjuku_speedrun.hanjuku.flows import boss_pursuit as bp


def map_screen():
    return SimpleNamespace(kind='map', marker=None, cursor=None, text='',
                           hand=None, selected=None)


def memory(tick=10000, **extra):
    mem = {
        'chapter': 9,
        'tick': tick,
        'world': {'sorties': {}, 'garrison': {}},
        # a fresh wave: the stale-wave gate has its own test file
        bp.LIST_KEY: {'ミント': {'step': 'A', 'launched': tick - 500}},
        'boss_cell': {'chapter': 9, 'cell': [810, 645], 'tick': tick - 10,
                      'readings': 2},
        'plan': {'active': None},
    }
    mem.update(extra)
    return mem


def arm(monkeypatch):
    monkeypatch.setattr(bp.chart, 'moving_boss_cell', lambda ch: (810, 645))


def test_two_pursuit_starts_inside_the_gap_are_refused(monkeypatch):
    arm(monkeypatch)
    mem = memory()
    assert bp.step(map_screen(), mem, None) == []
    assert mem['boss_pursuit']['general'] == 'ミント'
    assert mem['boss_pursuit_start_tick'] == 10000

    # A probe that closed on the map must not start the next one immediately.
    bp._drop_probe(mem)
    mem['tick'] = 10000 + bp.PURSUIT_START_GAP - 1
    assert bp.step(map_screen(), mem, None) is None
    assert 'boss_pursuit' not in mem
    assert mem['boss_pursuit_start_tick'] == 10000


def test_the_next_start_is_allowed_once_the_gap_elapsed(monkeypatch):
    arm(monkeypatch)
    mem = memory()
    assert bp.step(map_screen(), mem, None) == []
    bp._drop_probe(mem)
    mem['tick'] = 10000 + bp.PURSUIT_START_GAP
    assert bp.step(map_screen(), mem, None) == []
    queued = [r for r in mem.get('_records', [])
              if r['decision'] == 'boss_pursuit_queued']
    assert queued[-1]['observed_metric']['since_last_start'] == bp.PURSUIT_START_GAP
    assert mem['boss_pursuit_start_tick'] == 10000 + bp.PURSUIT_START_GAP


def test_a_hot_loaded_memory_without_the_clock_starts_normally(monkeypatch):
    # A policy hot-loaded over the old build carries no pacing clock; the first
    # pursuit must not be blocked by a missing (or foreign) value.
    arm(monkeypatch)
    mem = memory()
    assert bp.step(map_screen(), mem, None) == []
    mem.pop('boss_pursuit_start_tick')
    bp._drop_probe(mem)
    mem['tick'] = 10030
    mem['boss_pursuit_start_tick'] = 'stale'
    assert bp.step(map_screen(), mem, None) == []
    assert mem['boss_pursuit_start_tick'] == 10030
